import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),s={name:"privacy.md"};function n(i,e,l,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>This notice describes how the <strong>CharacterVault</strong> web app handles information when you use the hosted site or a self-hosted copy.</p><p>CharacterVault is open source under the <a href="https://github.com/spaceman2408/CharacterVault/blob/main/LICENSE" target="_blank" rel="noreferrer">GNU General Public License v3.0</a>. This page is about privacy, not the software license.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li>Character cards and settings are stored <strong>in your browser</strong> (IndexedDB and related local storage).</li><li>CharacterVault does <strong>not</strong> provide accounts, cloud sync, or a backend that stores your cards.</li><li>Optional <strong>AI features</strong> send content to the provider <strong>you</strong> configure; that is outside CharacterVault’s control.</li><li>The public app is served from <strong>GitHub Pages</strong>; GitHub may process standard website access data under their policies.</li></ul><h2 id="local-data" tabindex="-1">Local data <a class="header-anchor" href="#local-data" aria-label="Permalink to &quot;Local data&quot;">​</a></h2><p>When you create or edit characters and <strong>standalone lorebooks</strong>, data such as card fields, images, lorebook entries, snapshots, attachment links, app settings, and optional <strong>custom AI context</strong> notes is kept locally in your browser. It is not uploaded to a CharacterVault server, because the core app has no such server.</p><p>Custom context and lorebook <strong>links</strong> (which library book a character uses) stay in this browser only. They are not written into PNG/JSON by themselves. The lorebook <strong>text on the character</strong> is what card export includes — and after you link a book, that text stays matched with the library book. Clearing site data, using a different browser or device, or uninstalling browser storage for this origin can remove local data. Export cards, lorebook JSON, or vault backups for portable copies; keep a separate copy of custom notes if you need them elsewhere.</p><h2 id="hosted-site-github-pages" tabindex="-1">Hosted site (GitHub Pages) <a class="header-anchor" href="#hosted-site-github-pages" aria-label="Permalink to &quot;Hosted site (GitHub Pages)&quot;">​</a></h2><p>The public build at <a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">spaceman2408.github.io/CharacterVault</a> is hosted on <strong>GitHub Pages</strong>. CharacterVault’s maintainers do not operate a separate application server for the core product.</p><p>Like most static sites, hosting may involve normal web request metadata (for example IP address, user agent, and requested URLs). That processing is governed by <a href="https://docs.github.com/en/site-policy/privacy-policies/github-privacy-statement" target="_blank" rel="noreferrer">GitHub’s Privacy Statement</a>, not by a CharacterVault database of user accounts.</p><p>If you run CharacterVault yourself (local build or your own host), only that host’s operators and your browser apply.</p><h2 id="ai-features-optional" tabindex="-1">AI features (optional) <a class="header-anchor" href="#ai-features-optional" aria-label="Permalink to &quot;AI features (optional)&quot;">​</a></h2><p>AI tools (Orion chat, the Agent, the AI toolbar, AI Creation Studio, and similar) only work after you configure a provider (API base URL, key, and model, or a sign-in flow such as NanoGPT where offered).</p><p>When you use those features, text and context you send (for example selected sections of a card, enabled custom context notes, chat messages, Agent catalogs and field or entry bodies it reads, or generation prompts) are transmitted to <strong>that provider</strong> so a model can respond. CharacterVault does not intermediate those requests through a CharacterVault-owned AI backend for the standard open-source app.</p><ul><li>Your provider’s privacy policy and terms apply to that traffic.</li><li>API keys and related credentials are stored <strong>locally</strong> in your browser settings, not on CharacterVault servers.</li><li>If you self-host optional helpers (for example a NanoGPT usage proxy), traffic and logs for that component follow <strong>your</strong> deployment and configuration.</li></ul><h2 id="what-we-do-not-do" tabindex="-1">What we do not do <a class="header-anchor" href="#what-we-do-not-do" aria-label="Permalink to &quot;What we do not do&quot;">​</a></h2><p>For the standard browser app and public GitHub Pages build, CharacterVault maintainers do not:</p><ul><li>Require an account to use core library and editor features</li><li>Sell your character cards or settings</li><li>Run a CharacterVault cloud store of your library</li></ul><p>Third-party sites and extensions you choose to use (SillyTavern, model hosts, browsers, and so on) have their own policies.</p><h2 id="cookies-and-similar-storage" tabindex="-1">Cookies and similar storage <a class="header-anchor" href="#cookies-and-similar-storage" aria-label="Permalink to &quot;Cookies and similar storage&quot;">​</a></h2><p>CharacterVault uses browser storage needed to run the app (for example IndexedDB for characters, and local settings such as theme or dismissed UI hints). It is not an advertising product and does not load third-party ad trackers as part of the core app.</p><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;Children&quot;">​</a></h2><p>CharacterVault is a general-purpose creative tool. It is not directed at children, and we do not knowingly collect personal information from children through a CharacterVault account system (there is no such system).</p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><p>This notice may be updated as the project changes. The current version lives in the repository and on the docs site. Material changes should be reflected there when the site is redeployed.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions or concerns: open an issue on the <a href="https://github.com/spaceman2408/CharacterVault" target="_blank" rel="noreferrer">CharacterVault GitHub repository</a>.</p><hr><p><em>This page is informational and is not legal advice.</em></p>',30)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
